error_reporting(E_ALL);
set_error_handler(function($level,$message,$file,$line){if($level & error_reporting())throw new ErrorException($message,0,$level,$file,$line);});
$checks=0;
function expect($ok,$message){global $checks;$checks++;if(!$ok)throw new RuntimeException($message);}
function fails($fn,$fragment){try{$fn();}catch(Throwable $e){expect(strpos($e->getMessage(),$fragment)!==false,'Expected rejection: '.$fragment.'; got '.$e->getMessage());return;}throw new RuntimeException('Expected failure: '.$fragment);}
function policy($value){DB::table('tblsahdev_settings')->where('id',1)->update(['copilot_database_policy_json'=>json_encode($value)]);}
function revision(){return hash('sha256',(string)DB::table('tblsahdev_settings')->value('copilot_database_policy_json'));}
function makePlan($resource,$operation,$id,$values=[],$parent=0,$admin=1){return Safe::handleOperationRequest('database_plan',['resource'=>$resource,'operation'=>$operation,'record_id'=>$id,'parent_id'=>$parent,'values_json'=>json_encode($values)],$admin,$admin);}
function executePlan($plan,$password=null,$admin=1){return Ops::execute($plan['action_key'],$plan['params'],$admin,$admin,$password,$plan['proposal_id']);}
function good($result,$message){expect(!empty($result['success']),$message.': '.($result['error']??''));}

